// Hiding network calls behind local traits that lack network failure or latency semantics
trait UserRepository {
    fn get_user(&self, id: u64) -> Result<User, ()>; // Generic error, no timeout/retry context
}

struct RemoteUserRepository;

impl UserRepository for RemoteUserRepository {
    fn get_user(&self, id: u64) -> Result<User, ()> {
        // Blocks on synchronous network HTTP call
        let response = reqwest::blocking::get(&format!("http://api/users/{}", id))
            .map_err(|_| ())?;
        response.json::<User>().map_err(|_| ())
    }
}
